function L({registerIndicator:C,nulls:k}){C({id:"oa-chop",name:"Choppiness Index",category:"Dynamics",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:2,max:5e3,step:1}],plots:[{key:"chop",type:"line",title:"CHOP",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:61.8,title:"High Threshold",color:"#ef5350",dashed:!0},{price:38.2,title:"Low Threshold",color:"#26a69a",dashed:!0},{price:50,title:"Midline",color:"#787b86",dashed:!0}],calc(n,B){const t=Math.max(2,Math.floor(Number(B.length)||14)),f=n.length,N=new Array(f).fill(NaN),p=new Array(t).fill(NaN),d=new Array(t).fill(NaN),b=new Array(t).fill(NaN);let h=0,i=0,g=0;for(let e=0;e<f;e++){const a=Number(n[e].high),s=Number(n[e].low),M=Number(n[e].close);if(!Number.isFinite(a)||!Number.isFinite(s)||!Number.isFinite(M))continue;const y=e>0?Number(n[e-1].close):NaN,w=Number.isFinite(y)?y:M,x=Math.max(a-s,Math.max(Math.abs(a-w),Math.abs(s-w))),v=p[i];Number.isFinite(v)?h-=v:g+=1,p[i]=x,d[i]=a,b[i]=s,h+=x;const r=Math.min(g,t);let u=-1e100,m=1e100;for(let o=0;o<r;o++){const c=(i-o+t)%t,l=d[c],A=b[c];Number.isFinite(l)&&(u=Math.max(u,l)),Number.isFinite(A)&&(m=Math.min(m,A))}i=(i+1)%t;const F=u-m;if(r>=2&&F>0){const o=Math.log10(h/F),c=Math.log10(r);let l=100*o/c;l=Math.max(0,Math.min(100,l)),N[e]=l}}return{chop:k(N)}}})}export{L as default};
